import React, { useMemo, useState } from "react";

function App() {
  const [isLogin, setIsLogin] = useState(false);

  const [signupData, setSignupData] = useState({
    firstName: "",
    surname: "",
    day: "",
    month: "",
    year: "",
    gender: "",
    emailOrMobile: "",
    password: "",
  });

  const [loginData, setLoginData] = useState({
    emailOrMobile: "",
    password: "",
  });

  const [popup, setPopup] = useState({
    show: false,
    title: "",
    message: "",
    type: "success",
  });

  const days = useMemo(
    () => Array.from({ length: 31 }, (_, i) => i + 1),
    []
  );

  const months = useMemo(
    () => [
      "January",
      "February",
      "March",
      "April",
      "May",
      "June",
      "July",
      "August",
      "September",
      "October",
      "November",
      "December",
    ],
    []
  );

  const years = useMemo(() => {
    const currentYear = new Date().getFullYear();
    const list = [];
    for (let y = currentYear; y >= 1950; y--) {
      list.push(y);
    }
    return list;
  }, []);

  const showPopup = (title, message, type = "success") => {
    setPopup({
      show: true,
      title,
      message,
      type,
    });
  };

  const closePopup = () => {
    setPopup({
      show: false,
      title: "",
      message: "",
      type: "success",
    });
  };

  const handleSignupChange = (e) => {
    setSignupData({ ...signupData, [e.target.name]: e.target.value });
  };

  const handleLoginChange = (e) => {
    setLoginData({ ...loginData, [e.target.name]: e.target.value });
  };

  const handleSignupSubmit = async (e) => {
    e.preventDefault();

    try {
      const payload = {
        firstName: signupData.firstName,
        surname: signupData.surname,
        day: signupData.day,
        month: signupData.month,
        year: signupData.year,
        gender: signupData.gender,
        emailOrMobile: signupData.emailOrMobile,
        password: signupData.password,
      };

      const response = await fetch("http://localhost:8081/api/v1/auth/register", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      const text = await response.text();

      if (response.ok) {
        showPopup(
          "Registration Successful",
          "You have successfully registered an account."
        );

        setSignupData({
          firstName: "",
          surname: "",
          day: "",
          month: "",
          year: "",
          gender: "",
          emailOrMobile: "",
          password: "",
        });
      } else {
        showPopup(
          "Registration Failed",
          text || "Unable to register account.",
          "error"
        );
      }
    } catch (error) {
      showPopup(
        "Server Error",
        "Could not connect to the backend.",
        "error"
      );
    }
  };

  const handleLoginSubmit = async (e) => {
    e.preventDefault();

    try {
      const payload = {
        emailOrMobile: loginData.emailOrMobile,
        password: loginData.password,
      };

      const response = await fetch("http://localhost:8081/api/v1/auth/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      const text = await response.text();

      if (response.ok) {
        showPopup("Login Successful", "You have successfully logged in.");

        setLoginData({
          emailOrMobile: "",
          password: "",
        });
      } else {
        showPopup(
          "Login Failed",
          text || "Invalid login credentials.",
          "error"
        );
      }
    } catch (error) {
      showPopup(
        "Server Error",
        "Could not connect to the backend.",
        "error"
      );
    }
  };

  return (
    <>
      <div className="auth-page">
        <div className="auth-card">
          {!isLogin ? (
            <>
              <div className="auth-left">
                <h1 className="auth-title">SIGN UP</h1>
                <p className="auth-subtitle">Get started on RentMate</p>

                <form onSubmit={handleSignupSubmit}>
                  <div className="row two-cols">
                    <div className="form-group">
                      <label>First Name</label>
                      <input
                        type="text"
                        name="firstName"
                        placeholder="First name"
                        value={signupData.firstName}
                        onChange={handleSignupChange}
                        required
                      />
                    </div>

                    <div className="form-group">
                      <label>Surname</label>
                      <input
                        type="text"
                        name="surname"
                        placeholder="Surname"
                        value={signupData.surname}
                        onChange={handleSignupChange}
                        required
                      />
                    </div>
                  </div>

                  <div className="form-group">
                    <label>Date of Birth</label>
                    <div className="row three-cols">
                      <select
                        name="day"
                        value={signupData.day}
                        onChange={handleSignupChange}
                        required
                      >
                        <option value="">Day</option>
                        {days.map((day) => (
                          <option key={day} value={day}>
                            {day}
                          </option>
                        ))}
                      </select>

                      <select
                        name="month"
                        value={signupData.month}
                        onChange={handleSignupChange}
                        required
                      >
                        <option value="">Month</option>
                        {months.map((month) => (
                          <option key={month} value={month}>
                            {month}
                          </option>
                        ))}
                      </select>

                      <select
                        name="year"
                        value={signupData.year}
                        onChange={handleSignupChange}
                        required
                      >
                        <option value="">Year</option>
                        {years.map((year) => (
                          <option key={year} value={year}>
                            {year}
                          </option>
                        ))}
                      </select>
                    </div>
                  </div>

                  <div className="form-group">
                    <label>Gender</label>
                    <select
                      name="gender"
                      value={signupData.gender}
                      onChange={handleSignupChange}
                      required
                    >
                      <option value="">Select your gender</option>
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                      <option value="Prefer not to say">Prefer not to say</option>
                    </select>
                  </div>

                  <div className="form-group">
                    <label>Email or Mobile Number</label>
                    <input
                      type="text"
                      name="emailOrMobile"
                      placeholder="Enter Mobile Number or Email Address"
                      value={signupData.emailOrMobile}
                      onChange={handleSignupChange}
                      required
                    />
                  </div>

                  <div className="form-group">
                    <label>Password</label>
                    <input
                      type="password"
                      name="password"
                      placeholder="Enter Password"
                      value={signupData.password}
                      onChange={handleSignupChange}
                      required
                    />
                  </div>

                  <button type="submit" className="primary-btn">
                    CREATE ACCOUNT
                  </button>
                </form>
              </div>

              <div className="auth-right">
                <div className="brand-box">
                  <h2>RentMate</h2>
                  <p>
                    Already have an account? Sign in and continue exploring
                    rentals.
                  </p>
                  <button
                    className="secondary-btn"
                    onClick={() => setIsLogin(true)}
                  >
                    SIGN IN
                  </button>
                </div>
              </div>
            </>
          ) : (
            <>
              <div className="auth-right auth-right-left">
                <div className="brand-box">
                  <h2>RentMate</h2>
                  <p>Create an account and start your rental journey with us.</p>
                  <button
                    className="secondary-btn"
                    onClick={() => setIsLogin(false)}
                  >
                    SIGN UP
                  </button>
                </div>
              </div>

              <div className="auth-left">
                <h1 className="auth-title">SIGN IN</h1>
                <p className="auth-subtitle">Sign in with your account</p>

                <form onSubmit={handleLoginSubmit}>
                  <div className="form-group">
                    <label>Email or Mobile Number</label>
                    <input
                      type="text"
                      name="emailOrMobile"
                      placeholder="Enter Mobile Number or Email Address"
                      value={loginData.emailOrMobile}
                      onChange={handleLoginChange}
                      required
                    />
                  </div>

                  <div className="form-group">
                    <label>Password</label>
                    <input
                      type="password"
                      name="password"
                      placeholder="Enter Password"
                      value={loginData.password}
                      onChange={handleLoginChange}
                      required
                    />
                  </div>

                  <button type="submit" className="primary-btn">
                    SIGN IN
                  </button>
                </form>
              </div>
            </>
          )}
        </div>
      </div>

      {popup.show && (
        <div className="popup-overlay">
          <div className={`popup-box ${popup.type}`}>
            <h3>{popup.title}</h3>
            <p>{popup.message}</p>
            <button onClick={closePopup}>OK</button>
          </div>
        </div>
      )}
    </>
  );
}

export default App;
